#!/usr/bin/env node
// Build functions/_lib/pfa/generated/bundle.generated.js: the compiled PFA data plus the inline CSS
// and the inline browser runtime the server renderer embeds in every page.
//
//   node scripts/pfa/build-pfa-bundle.mjs           write it
//   node scripts/pfa/build-pfa-bundle.mjs --check   fail when it is stale (freshness gate)
//
// Why one generated module: the pages are rendered by a Pages Function so they add no files to dist/
// (which sits at Cloudflare's 20,000-file limit), and a Function cannot read data/ at runtime.

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const LIB = join(ROOT, "functions/_lib/pfa");
const OUT = join(LIB, "generated/bundle.generated.js");
const read = (p) => readFileSync(join(ROOT, p), "utf8");

function css() {
  return read("functions/_lib/pfa/design-system.css")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/\s*\n\s*/g, "\n")
    .replace(/\s*([{};,])\s*/g, "$1")
    .replace(/\n+/g, "")
    .trim();
}

// Concatenate the shared modules into one module-scoped script: drop import lines and `export`.
export function clientJs(lite = false) {
  const files = lite
    ? ["strings.js", "problem-view.js", "insight-code.js", "client-runtime.js", "client-premium.js"]
    : [
        "generators.js",
        "math-visuals.js",
        "strings.js",
        "problem-view.js",
        "insight-code.js",
        "client-runtime.js",
        "client-premium.js",
      ];
  const parts = files.map((f) => {
    const src = readFileSync(join(LIB, f), "utf8");
    return src
      .split("\n")
      .filter((line) => !/^\s*import\s.+from\s+["'].+["'];?\s*$/.test(line))
      .filter((line) => !/^\s*\/\//.test(line))
      .filter((line) => !/^\s*\/\* global /.test(line))
      .map((line) => line.replace(/^export\s+(const|function|let)\s/, "$1 "))
      .join("\n");
  });
  // Client-drawn SVGs must not reuse the server's mv1..mvN title ids: reset the counter just before
  // the browser runtime (client-runtime.js and the premium layer after it) starts drawing.
  const rt = files.indexOf("client-runtime.js");
  const js = lite
    ? parts.join("\n")
    : `${parts.slice(0, rt).join("\n")}\nuid = 100000;\n${parts.slice(rt).join("\n")}`;
  return js.replace(/<\/script/gi, "<\\/script").replace(/\n{2,}/g, "\n");
}

function data() {
  const strip = (o) => {
    const { selection, ...rest } = o;
    return rest;
  };
  const practice = {};
  const family = {};
  for (const f of readdirSync(join(ROOT, "data/practice"))
    .filter((x) => x.endsWith(".json") && !x.startsWith("_"))
    .sort()) {
    const d = JSON.parse(read(`data/practice/${f}`));
    practice[d.lessonId] = strip(d);
  }
  for (const f of readdirSync(join(ROOT, "data/family"))
    .filter((x) => x.endsWith(".json"))
    .sort()) {
    const d = JSON.parse(read(`data/family/${f}`));
    family[d.lessonId] = d;
  }
  const map = JSON.parse(read("data/assignments.json"));
  const taxonomy = JSON.parse(read("data/misconception-taxonomy.json")).taxonomy;
  map.taxonomyLabels = Object.fromEntries(
    Object.entries(taxonomy).map(([k, v]) => [k, { en: v.label, es: v.labelEs || v.label }]),
  );
  // Student coaching line (finish card) and teacher "watch for" line (class insights).
  map.taxonomyStudent = Object.fromEntries(
    Object.entries(taxonomy)
      .filter(([, v]) => v.student && v.studentEs)
      .map(([k, v]) => [k, { en: v.student, es: v.studentEs }]),
  );
  map.taxonomyWatch = Object.fromEntries(
    Object.entries(taxonomy)
      .filter(([, v]) => v.watchFor)
      .map(([k, v]) => [k, v.watchFor]),
  );
  // Lessons in the order they are TAUGHT (district pacing: unit order from
  // data/pacing-unit-ranges.json, then lesson number), for spiral review.
  const pacing = JSON.parse(read("data/pacing-unit-ranges.json"));
  const unitOrder = pacing.units.map((u) => u.curriculumUnit).filter((u) => Number.isInteger(u));
  map.sequence = unitOrder.flatMap((u) =>
    map.lessons
      .filter((L) => L.unit === u)
      .sort((a, b) => a.lesson - b.lesson)
      .map((L) => L.id),
  );
  return { practice, family, map };
}

export function build() {
  const { practice, family, map } = data();
  const CSS = css();
  const CLIENT_JS = clientJs();
  const CLIENT_LITE = clientJs(true);
  const body = `export const CSS = ${JSON.stringify(CSS)};\nexport const CLIENT_JS = ${JSON.stringify(CLIENT_JS)};\nexport const CLIENT_LITE = ${JSON.stringify(CLIENT_LITE)};\nexport const PRACTICE = ${JSON.stringify(practice)};\nexport const FAMILY = ${JSON.stringify(family)};\nexport const MAP = ${JSON.stringify(map)};\n`;
  const BUILD = createHash("sha256").update(body).digest("hex").slice(0, 12);
  return `// GENERATED by scripts/pfa/build-pfa-bundle.mjs — do not edit. Source: functions/_lib/pfa/*.{js,css}, data/practice, data/family, data/assignments.json.\n// biome-ignore-all format: generated\nexport const BUILD = ${JSON.stringify(BUILD)};\n${body}`;
}

const isMain = import.meta.url === `file://${process.argv[1]}`;
if (isMain) {
  const text = build();
  if (process.argv.includes("--check")) {
    const cur = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
    if (cur !== text) {
      console.error(
        "FAIL pfa-bundle: functions/_lib/pfa/generated/bundle.generated.js is stale. Run: node scripts/pfa/build-pfa-bundle.mjs",
      );
      process.exit(1);
    }
    console.log("PASS pfa-bundle: generated bundle matches its sources");
  } else {
    mkdirSync(dirname(OUT), { recursive: true });
    writeFileSync(OUT, text);
    console.log(
      `pfa-bundle: wrote ${OUT.replace(`${ROOT}/`, "")} (${(text.length / 1024).toFixed(0)} KB; client ${(clientJs().length / 1024).toFixed(0)} KB, css ${(css().length / 1024).toFixed(0)} KB)`,
    );
  }
}
